    // Parse the query
    expr, err := parser.ParseExpr(qs)
    if err != nil {
        return nil, err
    }

    // Create query plan
    plan := &QueryPlan{
        QueryString: qs,
        ParsedAST:   expr,
    }

    // Analyze execution steps
    steps, err := ng.analyzeExecutionSteps(expr)
    if err != nil {
        return nil, err
    }
    plan.ExecutionSteps = steps

    // Estimate resources
    seriesEst, samplesEst, err := ng.estimateResources(expr)
    if err != nil {
        return nil, err
    }
    plan.EstimatedSeries = seriesEst
    plan.EstimatedSamples = samplesEst

    // Check for warnings
    plan.Warnings = ng.checkForWarnings(expr)

    return plan, nil
}
```

